"""PWA + Android (Trusted Web Activity) support for the dashboard.

Serves: web app manifest, service worker (navigation-only, never caches API or
logged-in data), offline page, icons, Digital Asset Links for the Play Store
app, and the public legal pages Google Play requires (privacy policy, terms,
account-deletion page). Everything is public (no login) and has no external
dependency; icons are embedded so there are no extra files to upload.

Environment (Railway variables), all optional:
  ANDROID_PACKAGE        Play Store application id, e.g. com.herobotai.app
  ANDROID_SHA256_CERT    SHA-256 fingerprint(s) of the app SIGNING key (comma separated),
                         copied from Play Console -> App integrity (Play App Signing)
  SUPPORT_EMAIL          contact address shown in the legal pages
  SERVICE_NAME           default Herobot-AI
"""
import base64
import json
import os

SERVICE_NAME = os.environ.get('SERVICE_NAME', 'Herobot-AI')
SUPPORT_EMAIL = os.environ.get('SUPPORT_EMAIL', '').strip()
ANDROID_PACKAGE = os.environ.get('ANDROID_PACKAGE', 'com.herobotai.app').strip()
ANDROID_SHA256 = [x.strip().upper() for x in os.environ.get('ANDROID_SHA256_CERT', '').split(',') if x.strip()]

_ICONS = {
    '/icons/icon-192.png': base64.b64decode(""),
    '/icons/icon-512.png': base64.b64decode(""),
    '/icons/icon-maskable-512.png': base64.b64decode(""),
}

HEAD_INJECT = ('<link rel="manifest" href="/manifest.webmanifest">'
               '<meta name="theme-color" content="#0D1114">'
               '<meta name="mobile-web-app-capable" content="yes">'
               '<link rel="icon" type="image/png" href="/icons/icon-192.png">'
               '<link rel="apple-touch-icon" href="/icons/icon-192.png">')
BODY_INJECT = ("<script>if('serviceWorker' in navigator){window.addEventListener('load',function(){"
               "navigator.serviceWorker.register('/sw.js').catch(function(){})})}</script>")


def inject(html):
    """Adds the manifest/theme-color tags and the service worker registration to a page."""
    if 'rel="manifest"' not in html and '</head>' in html:
        html = html.replace('</head>', HEAD_INJECT + '</head>', 1)
    if "serviceWorker.register" not in html and '</body>' in html:
        html = html.replace('</body>', BODY_INJECT + '</body>', 1)
    return html


MANIFEST = {
    'name': SERVICE_NAME, 'short_name': 'Herobot', 'description': 'Kripto, Borsa İstanbul ve Wall Street tarama ve işlem takibi',
    'id': '/', 'start_url': '/?source=app', 'scope': '/', 'display': 'standalone', 'orientation': 'portrait',
    'background_color': '#0D1114', 'theme_color': '#0D1114', 'lang': 'tr',
    'icons': [
        {'src': '/icons/icon-192.png', 'sizes': '192x192', 'type': 'image/png', 'purpose': 'any'},
        {'src': '/icons/icon-512.png', 'sizes': '512x512', 'type': 'image/png', 'purpose': 'any'},
        {'src': '/icons/icon-maskable-512.png', 'sizes': '512x512', 'type': 'image/png', 'purpose': 'maskable'},
    ],
}

SERVICE_WORKER = """const V='herobot-v1';
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(V).then(c=>c.add('/offline')))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==V).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
// Only page navigations are handled (offline fallback). API calls and logged-in data are never cached.
self.addEventListener('fetch',e=>{if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('/offline')))}});
"""

OFFLINE_HTML = """<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bağlantı yok</title><style>body{margin:0;background:#0D1114;color:#e6edf3;font-family:system-ui,sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;text-align:center;padding:24px}
button{margin-top:16px;padding:10px 20px;border-radius:8px;border:1px solid #d4a85a;background:transparent;color:#d4a85a;font-size:15px}</style></head>
<body><div><h2>İnternet bağlantısı yok</h2><p>Bağlantı kurulunca devam edebilirsiniz.</p><button onclick="location.reload()">Yeniden dene</button></div></body></html>"""


def assetlinks():
    if not ANDROID_SHA256:
        return []
    return [{'relation': ['delegate_permission/common.handle_all_urls'],
             'target': {'namespace': 'android_app', 'package_name': ANDROID_PACKAGE, 'sha256_cert_fingerprints': ANDROID_SHA256}}]


def get(path):
    """(status, content_type, body_bytes, extra_headers) for a PWA path, or None if it is not one."""
    if path in _ICONS:
        return 200, 'image/png', _ICONS[path], [('Cache-Control', 'public, max-age=86400')]
    if path == '/manifest.webmanifest':
        return 200, 'application/manifest+json; charset=utf-8', json.dumps(MANIFEST, ensure_ascii=False).encode(), [('Cache-Control', 'no-cache')]
    if path == '/sw.js':
        return 200, 'application/javascript; charset=utf-8', SERVICE_WORKER.encode(), [('Cache-Control', 'no-cache'), ('Service-Worker-Allowed', '/')]
    if path == '/offline':
        return 200, 'text/html; charset=utf-8', OFFLINE_HTML.encode(), [('Cache-Control', 'no-cache')]
    if path == '/.well-known/assetlinks.json':
        return 200, 'application/json', json.dumps(assetlinks()).encode(), [('Cache-Control', 'no-cache')]
    return None


