def _contact_tr():
    return (f'<a href="mailto:{SUPPORT_EMAIL}">{SUPPORT_EMAIL}</a> adresine yazabilir veya' if SUPPORT_EMAIL else '') + ' giriş yaptıktan sonra Hesabım sayfasındaki mesaj formunu kullanabilirsiniz.'


def _contact_en():
    return (f'You can write to <a href="mailto:{SUPPORT_EMAIL}">{SUPPORT_EMAIL}</a> or' if SUPPORT_EMAIL else 'You can') + ' use the message form on the My Account page after signing in.'


