def delete_account_html():
    body = f"""<h1>Hesap ve Veri Silme</h1>
<p>Hesabınızın ve ilişkili verilerin (işlem kayıtları, ayarlar, Telegram bağlantısı, kayıtlı API anahtarları) silinmesini buradan talep edebilirsiniz.</p>
<div class="card"><b>Önemli:</b> Silme talebinden önce Binance hesabınızda botun açtığı açık pozisyonlar varsa kapatılmasını sağlayın. Talep onaylandığında canlı işlem durdurulur ve verileriniz silinir. Yasal yükümlülükler gerektirenler dışındaki veriler silinir.</div>
<div id="box" class="card">Yükleniyor…</div>
<p>Giriş yapamıyorsanız: {_contact_tr()}</p>
<hr><h1>Account and Data Deletion</h1>
<p>You can request deletion of your account and related data (trade records, settings, Telegram link, stored API keys) here. Close any open positions the bot opened on your Binance account first. Once processed, live trading stops and your data is deleted, except what the law requires us to keep.</p>
<script>
(async function(){{
  var box=document.getElementById('box');
  var me=null; try{{ var r=await fetch('/api/account',{{cache:'no-store'}}); if(r.ok) me=await r.json(); }}catch(e){{}}
  if(!me||!me.username){{ box.innerHTML='Silme talebi için önce <a href="/login">giriş yapın</a> (Sign in first).'; return; }}
  box.innerHTML='Hesap: <b></b><br><br><label><input type="checkbox" id="ok"> Hesabımın ve verilerimin silinmesini istiyorum (I want my account and data deleted)</label><br><br><button class="btn" id="go" disabled>Silme talebi gönder</button><div id="msg" style="margin-top:12px"></div>';
  box.querySelector('b').textContent=me.username;
  document.getElementById('ok').onchange=function(){{ document.getElementById('go').disabled=!this.checked; }};
  document.getElementById('go').onclick=async function(){{
    this.disabled=true;
    try{{ var r=await fetch('/api/account/delete-request',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:'{{}}'}}); var d=await r.json();
      document.getElementById('msg').textContent=d.ok?'Talebiniz alındı. İşlem tamamlandığında hesabınız silinecek.':(d.error||'Talep gönderilemedi.'); }}
    catch(e){{ document.getElementById('msg').textContent='Bağlantı hatası.'; }}
  }};
}})();
</script>"""
